b=Path('experiments/parallel-workers/cleanup_history');x=json.load(open('experiments/parallel-workers/failureindex/candidates.json'));expected=json.load(open(b/'recovered-candidate-hashes.json'));inv=json.load(open(b/'remote-inventory.json'));mapping=json.load(open(b/'candidate-mapping.json'));plan=json.load(open(b/'remote-plan.json'));added={}
original=''
for l in open('experiments/parallel-workers/failureindex/events.jsonl'):
 o=json.loads(l);i=o.get('item',{})
 if i.get('id')=='item_13' and i.get('aggregated_output'):original=i['aggregated_output']
for c in x['candidates']:
 if c['id'] in ['F12','F14']:
  for f in c['files']:
   marker=f['path']+'\\n'
   if marker in original and f['bytes']<=1300:
    data=original.split(marker,1)[1].encode()[:f['bytes']];h=hashlib.sha256(data).hexdigest();remote=mapping[f['path']];a=inv[c['root']]['files'][str(Path(remote).relative_to(inv[c['root']]['remote_root']))]
    assert h==a['sha256'];added[f['path']]=h
 if c['id']=='F20':
  for e in c['failure_evidence']:
   f=next(f for f in c['files'] if f['path']==e['path'])
   if len(e['matches'])==1 and e['matches'][0]['line']==1:
    data=(e['matches'][0]['excerpt']+'\\n').encode()
    if len(data)==f['bytes']:
     h=hashlib.sha256(data).hexdigest();remote=mapping[f['path']];a=inv[c['root']]['files'][str(Path(remote).relative_to(inv[c['root']]['remote_root']))];assert h==a['sha256'];added[f['path']]=h
expected.update(added);(b/'recovered-candidate-hashes.json').write_text(json.dumps(expected,indent=2)+'\\n')
for candidate,h in added.items():plan['deletes'][mapping[candidate]]=h
plan['pending']=[p for p in plan['pending'] if p['candidate'] not in added]
(b/'remote-plan.json').write_text(json.dumps(plan,indent=2)+'\\n');print('additionally recovered',len(added),'total verified',len(plan['deletes']),'remaining',len(plan['pending']))
